dfg 0.1.0;
// nb-p01-schependomlaan-spaces   graph e9ad9495c671
entities = duck.table@1(path: "{MODELS}/schependomlaan.duckdb", table: "EntityText");
  // Ok  table 38947 rows x 6 cols  sha 3d5953d5d659
  //   columns EntityIndex:Integer, StepId:Integer, GlobalId:Text, Name:Text, Category:Text, Type:Text
  //   [0] 316, 224, "1nOs6Hg0v9fR$sLR1LjIyX", "opgaand werk", "IFCWALLSTANDARDCASE", "IFC_kalkzandsteen_100mm 100"
  //   [1] 337, 478, "3vSAOyJwTEhQMEIJ6D9qRY", "liftputwand", "IFCBEAM", "IFC_betonopstort_220x345 220 x 345"
  //   [2] 350, 639, "1a49H1hof5wg_s62YvIj$u", "fund_strook", "IFCBEAM", "IFC_strookfundering_2600x550 2600 x 550"
spaces = table.filter@1(table: entities.table, expr: "Category == 'IFCSPACE'");
  // Ok  table 100 rows x 6 cols  sha 614d0e4b0f46
  //   columns EntityIndex:Integer, StepId:Integer, GlobalId:Text, Name:Text, Category:Text, Type:Text
  //   [0] 8307, 268319, "22lJvI_rz50umvUizzyEQi", "instal. ruimte", "IFCSPACE", "Technische ruimte"
  //   [1] 8319, 268689, "2dFicWHgz1KPbr5tHWzMcP", "entree", "IFCSPACE", "Verkeersruimte"
  //   [2] 8337, 269205, "3ZMk1e17XESP$vROePi38_", "berging", "IFCSPACE", "Onbenoemde ruimte"
storeys = duck.table@1(path: "{MODELS}/schependomlaan.duckdb", table: "StoreyOfElement");
  // Ok  table 3721 rows x 4 cols  sha bda4a8fdb2d6
  //   columns EntityIndex:Integer, StoreyIndex:Integer, StoreyName:Text, Depth:Integer
  //   [0] 1160, 307, "-1 fundering", 1
  //   [1] 8334, 1162, "00 begane grond", 2
  //   [2] 16520, 9692, "01 eerste verdieping", 2
placed = table.join@1(a: spaces.table, b: storeys.table, aKey: "EntityIndex", mode: "inner");
  // Ok  table 100 rows x 9 cols  sha a8484267dc29
  //   columns EntityIndex:Integer, StepId:Integer, GlobalId:Text, Name:Text, Category:Text, Type:Text, StoreyIndex:Integer, StoreyName:Text, Depth:Integer
  //   [0] 8307, 268319, "22lJvI_rz50umvUizzyEQi", "instal. ruimte", "IFCSPACE", "Technische ruimte", 1162, "00 begane grond", 1
  //   [1] 8319, 268689, "2dFicWHgz1KPbr5tHWzMcP", "entree", "IFCSPACE", "Verkeersruimte", 1162, "00 begane grond", 1
  //   [2] 8337, 269205, "3ZMk1e17XESP$vROePi38_", "berging", "IFCSPACE", "Onbenoemde ruimte", 1162, "00 begane grond", 1
perStorey = table.aggregate@1(table: placed.table, groupBy: "StoreyName", aggregates: "count(EntityIndex) as Spaces");
  // Ok  table 4 rows x 2 cols  sha 4db59ed8df8a
  //   columns StoreyName:Text, Spaces:Integer
  //   [0] "00 begane grond", 32
  //   [1] "01 eerste verdieping", 29
  //   [2] "02 tweede verdieping", 20
sorted = table.sort@1(table: perStorey.table, A: "StoreyName");
  // Ok  table 4 rows x 2 cols  sha 4db59ed8df8a
  //   columns StoreyName:Text, Spaces:Integer
  //   [0] "00 begane grond", 32
  //   [1] "01 eerste verdieping", 29
  //   [2] "02 tweede verdieping", 20
chart = chart.bar@1(table: sorted.table, labelColumn: "StoreyName", valueColumns: "Spaces", title: "Spaces per storey");
  // Ok
  //   table: table 4 rows x 2 cols  sha 4db59ed8df8a
  //     columns StoreyName:Text, Spaces:Integer
  //     chart 4 categories x 1 series: "Spaces"
  //     "00 begane grond": 32
  //     "01 eerste verdieping": 29
  //     "02 tweede verdieping": 20
  //     "03 derde verdieping": 19
  //   legend: table 0 rows x 9 cols  sha b47d2a37380c
  //     columns column:Text, domain:Text, role:Text, label:Text, value:Number, r:Number, g:Number, b:Number, count:Integer
  //     legend empty
total = table.aggregate@1(table: perStorey.table, groupBy: "", aggregates: "sum(Spaces) as Spaces");
  // Ok  table 1 rows x 1 cols  sha af208ac9231c
  //   columns Spaces:Integer
  //   [0] 100
